package org.retrobridge.galaxyservices.s2;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
public final class MainActivity extends Activity {
 TextView cameraStatus;TextView status;Handler handler=new Handler();final Runnable refresh=new Runnable(){public void run(){try{status.setText(new String(org.retrobridge.galaxyservices.Wire.readFile(new java.io.File(getFilesDir(),"status.txt")),"UTF-8"));}catch(Exception e){status.setText("Ready");}try{cameraStatus.setText(new String(org.retrobridge.galaxyservices.Wire.readFile(new java.io.File(getFilesDir(),"camera-status.txt")),"UTF-8"));}catch(Exception ignored){}handler.postDelayed(this,2000);}};
 public void onCreate(Bundle b){super.onCreate(b);if(!getIntent().getBooleanExtra("probe",false)){try{startActivity(new Intent().setClassName("org.retrobridge.callprobe","org.retrobridge.callprobe.ProbeActivity"));finish();return;}catch(Exception ignored){}}LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(16,16,16,16);status=new TextView(this);l.addView(status);Button start=new Button(this);start.setText("Start");l.addView(start);start.setOnClickListener(new View.OnClickListener(){public void onClick(View v){getSharedPreferences("settings",0).edit().putBoolean("enabled",true).commit();startService(new Intent(MainActivity.this,LegacyService.class));}});Button pause=new Button(this);pause.setText("Pause");l.addView(pause);pause.setOnClickListener(new View.OnClickListener(){public void onClick(View v){getSharedPreferences("settings",0).edit().putBoolean("enabled",false).commit();stopService(new Intent(MainActivity.this,LegacyService.class));status.setText("Paused");}});final CheckBox camera=new CheckBox(this);camera.setText("Back up camera photos and videos");camera.setChecked(getSharedPreferences("camera-backup",0).getBoolean("enabled",false));l.addView(camera);camera.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener(){public void onCheckedChanged(CompoundButton button,boolean checked){android.content.SharedPreferences p=getSharedPreferences("camera-backup",0);android.content.SharedPreferences.Editor edit=p.edit().putBoolean("enabled",checked);if(!p.contains("since"))edit.putLong("since",System.currentTimeMillis());edit.commit();if(checked)startService(new Intent(MainActivity.this,LegacyService.class).putExtra("camera",true));}});cameraStatus=new TextView(this);l.addView(cameraStatus);Button messages=new Button(this);messages.setText("Picture and video messages");l.addView(messages);messages.setOnClickListener(v->startActivity(new Intent(this,MediaSetupActivity.class)));TextView credit=new TextView(this);credit.setText("Weather: Open-Meteo - CC BY 4.0\nLocations: GeoNames");l.addView(credit);setContentView(l);if(getSharedPreferences("settings",0).getBoolean("enabled",true))startService(new Intent(this,LegacyService.class));if(getIntent().getBooleanExtra("probe",false))new Thread(new Runnable(){public void run(){Probe.run(MainActivity.this);}},"probe").start();}
 public void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(i.getBooleanExtra("probe",false))new Thread(new Runnable(){public void run(){Probe.run(MainActivity.this);}},"probe").start();}
 public void onResume(){super.onResume();handler.post(refresh);}public void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
